function Introduction () {
    if (false) {
        TutorialGuyText("Hey! I am the <c9>Tutorial Guy.")
        TutorialGuyText("I will teach you how to run the<c9> Boba Tea Shop.")
        CreateCustomer()
        TutorialGuyText("This is a <c9>customer.")
        TutorialGuyText("The <c9>Customer</c9> has said the order.")
        Cursor = sprites.create(img`
            3 3 3 3 3 3 3 3 3 3 
            3 3 3 3 3 3 3 3 3 3 
            3 3 3 3 3 3 3 3 3 3 
            3 3 3 3 3 3 3 3 3 3 
            3 3 3 3 3 3 3 3 3 3 
            3 3 3 3 3 3 3 3 3 3 
            3 3 3 3 3 3 3 3 3 3 
            3 3 3 3 3 3 3 3 3 3 
            3 3 3 3 3 3 3 3 3 3 
            3 3 3 3 3 3 3 3 3 3 
            `, SpriteKind.Mouse)
        Cursor.z = 10
        CreateNotePad()
        TutorialGuyText("Write it down by clicking the <c9> Notepad</c9> in the top left.")
    }
    Create_Kitchen()
    TutorialGuyText("Now Enter <c9>The Kitchen</c9>. This is where you will make the order")
    TutorialGuyText("First go to the <c9>Milk Station</c9>")
}
sprites.onOverlap(SpriteKind.Mouse, SpriteKind.Button, function (sprite, otherSprite) {
    sprite.setImage(img`
        2 2 2 2 2 2 2 2 2 2 
        2 3 3 3 3 3 3 3 3 2 
        2 3 3 3 3 3 3 3 3 2 
        2 3 3 3 3 3 3 3 3 2 
        2 3 3 3 3 3 3 3 3 2 
        2 3 3 3 3 3 3 3 3 2 
        2 3 3 3 3 3 3 3 3 2 
        2 3 3 3 3 3 3 3 3 2 
        2 3 3 3 3 3 3 3 3 2 
        2 2 2 2 2 2 2 2 2 2 
        `)
    if (browserEvents.MouseLeft.isPressed()) {
        ActualBttons(otherSprite, sprite)
    }
})
